SELECT SEQNO, SEC_TYPE_MODEL, SEC_DETAIL_TYPE_MODEL, FINPROD_ID, FINPROD_NAME, CURVE_GROUP_CODE, CURVE_TYPE, ISSMOOTH, SMOOTHSECTION, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, IS_BOTTOM_GRADE, BOTTOM_GRADE, EFF_DATE, INVALID_DATE FROM MOD_CURVE_CONFIG T1
1=1
AND T1.EFF_DATE <= #{searchDate} AND T1.INVALID_DATE >= #{searchDate}

SELECT
	CURVE_CODE
FROM
	MOD_CURVE_MAPPING


		and CURVE_GROUP_CODE = #{curveGroupCode}


		AND CURVE_TYPE = #{curveType}


		AND GRADE_RESULT = #{graderesult}
